ee:message.ee:set-payload:
%dw 2.0
output application/java
import wait from dw::Runtime
var stockLevels = { "SKU-BOOK": 10, "SKU-MUG": 3, "SKU-EBOOK": 9999, "SKU-POSTER": 0 }
var inStock = stockLevels[payload.sku] default 0
// SKU-BOOK is a slow lookup (300 ms), so under Parallel For Each it finishes after the items behind it.
var lookupMillis = if (payload.sku == "SKU-BOOK") 300 else 0
---
({ sku: payload.sku, quantity: payload.quantity, inStock: inStock, available: inStock >= payload.quantity } wait lookupMillis)
	++ { checkedAt: now() }
